CREATE CACHED TABLE "PUBLIC"."RUNS"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "GOAL" CLOB NOT NULL,
    "STATUS" ENUM('DRAFT','PLANNED','RUNNING','PAUSED','WAITING_APPROVAL','SUCCEEDED','FAILED','CANCELLED') NOT NULL,
    "PLAN_JSON" CLOB,
    "PROJECT_ID" BIGINT,
    "TOTAL_TOKENS" BIGINT,
    "TOTAL_COST_CENTS" BIGINT,
    "ERROR_MESSAGE" CHARACTER VARYING(2000),
    "CREATED_AT" TIMESTAMP(6),
    "UPDATED_AT" TIMESTAMP(6)
);
ALTER TABLE "PUBLIC"."RUNS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_H1" PRIMARY KEY("ID");

CREATE CACHED TABLE "PUBLIC"."AGENT_STEPS"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "RUN_ID" BIGINT NOT NULL,
    "SEQ_NO" INTEGER NOT NULL,
    "AGENT_TYPE" ENUM('SCRIPT','BOARD','VIDEO','EDIT','QC'),
    "NAME" CHARACTER VARYING(200),
    "STATUS" ENUM('PENDING','RUNNING','SUCCEEDED','FAILED','SKIPPED','CANCELLED') NOT NULL,
    "EPISODE_ID" BIGINT,
    "INPUT_SUMMARY" CLOB,
    "OUTPUT_SUMMARY" CLOB,
    "TOOL_CALLS_JSON" CLOB,
    "TOKENS_USED" BIGINT,
    "COST_CENTS" BIGINT,
    "COST_ESTIMATED" BOOLEAN DEFAULT FALSE,
    "LATENCY_MS" BIGINT,
    "ERROR_MESSAGE" CHARACTER VARYING(2000),
    "STARTED_AT" TIMESTAMP(6),
    "ENDED_AT" TIMESTAMP(6),
    "CREATED_AT" TIMESTAMP(6),
    "UPDATED_AT" TIMESTAMP(6)
);
ALTER TABLE "PUBLIC"."AGENT_STEPS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_H2" PRIMARY KEY("ID");

CREATE CACHED TABLE "PUBLIC"."PROMPT_TEMPLATES"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "AGENT_TYPE" ENUM('SCRIPT','BOARD','VIDEO','EDIT','QC') NOT NULL,
    "NAME" CHARACTER VARYING(200),
    "CONTENT" CLOB NOT NULL,
    "UPDATED_AT" TIMESTAMP(6)
);
ALTER TABLE "PUBLIC"."PROMPT_TEMPLATES" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_H3" PRIMARY KEY("ID");
ALTER TABLE "PUBLIC"."PROMPT_TEMPLATES" ADD CONSTRAINT "UK_PROMPT_TEMPLATE_AGENT" UNIQUE("AGENT_TYPE");

ALTER TABLE "PUBLIC"."VIDEO_TASKS" ADD COLUMN "TOKENS_USED" BIGINT;
ALTER TABLE "PUBLIC"."VIDEO_TASKS" ADD COLUMN "COST_CENTS" BIGINT;
ALTER TABLE "PUBLIC"."VIDEO_TASKS" ADD COLUMN "COST_ESTIMATED" BOOLEAN DEFAULT FALSE;
ALTER TABLE "PUBLIC"."VIDEO_TASKS" ADD COLUMN "MODEL_USED" CHARACTER VARYING(100);
